"""Semantic version parsing, comparison, and range matching.

Versions follow Semantic Versioning 2.0.0: ``MAJOR.MINOR.PATCH``, then an
optional pre-release (``-`` followed by dot-separated identifiers) and an
optional build (``+`` followed by dot-separated identifiers). Identifiers
are non-empty and made of ASCII letters, digits, and hyphens. Numeric parts
(MAJOR, MINOR, PATCH, and all-digit pre-release identifiers) must not have
leading zeros. Anything else is invalid and raises ``ValueError``.

Precedence (``compare``) follows the SemVer 2.0.0 rules: compare MAJOR,
MINOR, and PATCH numerically; a version with a pre-release is lower than
the same version without one; pre-release identifiers are compared left to
right, all-digit ones numerically and the rest in ASCII order, with
all-digit identifiers lower than the rest, and a shorter list lower when
all its identifiers equal the start of a longer one. Build metadata is
ignored.

Ranges (``satisfies``) are one or more comparator sets joined by ``||``; a
version satisfies the range if it satisfies any set. A set is one or more
comparators separated by whitespace, all of which must hold. A comparator
is a full version optionally prefixed by an operator:

- ``=`` (or no operator), ``>``, ``>=``, ``<``, ``<=``: by precedence.
- ``^X.Y.Z``: at least ``X.Y.Z`` and below the next version that changes
  the leftmost non-zero part, i.e. ``^1.2.3`` is ``>=1.2.3 <2.0.0``,
  ``^0.2.3`` is ``>=0.2.3 <0.3.0``, and ``^0.0.3`` is ``>=0.0.3 <0.0.4``.
- ``~X.Y.Z``: at least ``X.Y.Z`` and below ``X.(Y+1).0``.

A version with a pre-release satisfies a set only if some comparator in
that set has a pre-release on the same MAJOR.MINOR.PATCH (so
``1.2.3-beta.2`` satisfies ``>=1.2.3-beta.1`` but not ``>=1.0.0``).
Invalid ranges raise ``ValueError``.
"""

from __future__ import annotations

import re
from dataclasses import dataclass


_NUMERIC_RE = re.compile(r"[0-9]+\Z")
_VERSION_RE = re.compile(
    r"(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)"
    r"(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
    r"(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?\Z"
)

# Longest operators first so that, for example, ``>=`` is not read as ``>``.
_OPERATORS = (">=", "<=", "^", "~", ">", "<", "=")


@dataclass(frozen=True)
class Version:
    major: int
    minor: int
    patch: int
    prerelease: tuple[str, ...] = ()
    build: tuple[str, ...] = ()

    def __str__(self) -> str:
        """The version in canonical form, e.g. ``1.2.3-rc.1+build.5``."""
        text = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            text += "-" + ".".join(self.prerelease)
        if self.build:
            text += "+" + ".".join(self.build)
        return text


def parse(text: str) -> Version:
    """Parse a version string."""
    if not isinstance(text, str):
        raise ValueError(f"invalid version: {text!r}")
    match = _VERSION_RE.fullmatch(text)
    if match is None:
        raise ValueError(f"invalid version: {text!r}")

    major, minor, patch, prerelease_text, build_text = match.groups()

    prerelease: tuple[str, ...] = ()
    if prerelease_text is not None:
        prerelease = tuple(prerelease_text.split("."))
        for identifier in prerelease:
            if (
                _is_numeric(identifier)
                and len(identifier) > 1
                and identifier[0] == "0"
            ):
                raise ValueError(
                    f"invalid version: {text!r} "
                    "(leading zero in pre-release identifier)"
                )

    build: tuple[str, ...] = ()
    if build_text is not None:
        build = tuple(build_text.split("."))

    return Version(int(major), int(minor), int(patch), prerelease, build)


def compare(a: str | Version, b: str | Version) -> int:
    """Return -1, 0, or 1 as ``a`` has lower, equal, or higher precedence."""
    return _compare_versions(_as_version(a), _as_version(b))


def satisfies(version: str | Version, range_: str) -> bool:
    """Whether ``version`` is in ``range_``."""
    candidate = _as_version(version)
    alternatives = _parse_range(range_)
    return any(
        _set_satisfied(candidate, comparators) for comparators in alternatives
    )


def _is_numeric(identifier: str) -> bool:
    return _NUMERIC_RE.fullmatch(identifier) is not None


def _sign(value: int) -> int:
    return (value > 0) - (value < 0)


def _as_version(value: str | Version) -> Version:
    if isinstance(value, Version):
        return value
    if isinstance(value, str):
        return parse(value)
    raise ValueError(f"invalid version: {value!r}")


def _compare_versions(a: Version, b: Version) -> int:
    for left, right in (
        (a.major, b.major),
        (a.minor, b.minor),
        (a.patch, b.patch),
    ):
        result = _sign(left - right)
        if result:
            return result

    # A pre-release has lower precedence than the corresponding release.
    if not a.prerelease or not b.prerelease:
        return _sign(len(b.prerelease) - len(a.prerelease))

    for left, right in zip(a.prerelease, b.prerelease):
        left_numeric = _is_numeric(left)
        right_numeric = _is_numeric(right)
        if left_numeric and right_numeric:
            result = _sign(int(left) - int(right))
        elif left_numeric:
            result = -1
        elif right_numeric:
            result = 1
        else:
            result = _sign((left > right) - (left < right))
        if result:
            return result

    return _sign(len(a.prerelease) - len(b.prerelease))


def _split_identifiers(text: str, raw: str) -> tuple[str, ...]:
    identifiers = tuple(part.split(".") for part in ())
    return identifiers


def _parse_comparator(token: str) -> tuple[str, Version]:
    operator = ""
    version_text = token
    for candidate in _OPERATORS:
        if token.startswith(candidate):
            operator = candidate
            version_text = token[len(candidate) :]
            break
    return operator, parse(version_text)


def _parse_range(range_: str) -> tuple[tuple[tuple[str, Version], ...], ...]:
    if not isinstance(range_, str):
        raise ValueError(f"invalid range: {range_!r}")

    alternatives = []
    for alternative in range_.split("||"):
        alternative = alternative.strip()
        if not alternative:
            raise ValueError(f"invalid range: {range_!r} (empty comparator set)")
        comparators = tuple(
            _parse_comparator(token) for token in alternative.split()
        )
        alternatives.append(comparators)
    return tuple(alternatives)


def _caret_upper(version: Version) -> Version:
    if version.major != 0:
        return Version(version.major + 1, 0, 0)
    if version.minor != 0:
        return Version(0, version.minor + 1, 0)
    return Version(0, 0, version.patch + 1)


def _tilde_upper(version: Version) -> Version:
    return Version(version.major, version.minor + 1, 0)


def _comparator_satisfied(
    version: Version, operator: str, target: Version
) -> bool:
    if operator in ("", "="):
        return _compare_versions(version, target) == 0
    if operator == ">":
        return _compare_versions(version, target) > 0
    if operator == ">=":
        return _compare_versions(version, target) >= 0
    if operator == "<":
        return _compare_versions(version, target) < 0
    if operator == "<=":
        return _compare_versions(version, target) <= 0
    if operator == "^":
        return (
            _compare_versions(version, target) >= 0
            and _compare_versions(version, _caret_upper(target)) < 0
        )
    if operator == "~":
        return (
            _compare_versions(version, target) >= 0
            and _compare_versions(version, _tilde_upper(target)) < 0
        )
    raise ValueError(f"invalid comparator operator: {operator!r}")


def _set_satisfied(
    version: Version, comparators: tuple[tuple[str, Version], ...]
) -> bool:
    for operator, target in comparators:
        if not _comparator_satisfied(version, operator, target):
            return False

    if version.prerelease:
        base = (version.major, version.minor, version.patch)
        return any(
            target.prerelease
            and (target.major, target.minor, target.patch) == base
            for _, target in comparators
        )

    return True

